+
+  /** Returns the {@link ActionKey} of this action. */
+  public ActionKey getActionKey() {
+    return actionKey;
+  }
+
+  /** Returns underlying {@link Action} of this remote action. */
+  public Action getAction() {
+    return action;
+  }
+
+  public Digest getCommandHash() {
+    return commandHash;
+  }
+
+  public Command getCommand() {
