-
-  private void maybeCreateRspFile(
-      String ruleName,
-      NestedSetBuilder<Artifact> inputsBuilder,
-      ImmutableSortedMap<NinjaRuleVariable, String> ruleVariables)
-      throws GenericParsingException {
