-      NinjaToken token = lexer.nextToken();
-      if (token != NinjaToken.TEXT) {
-        lexer.undo();
-        break;
-      }
-      byte[] bytes = lexer.getTokenBytes();
-      boolean foundNonWhitespace = false;
-      for (int i = 0; i < bytes.length; i++) {
-        if (bytes[i] != ' ') {
-          foundNonWhitespace = true;
-          break;
-        }
-      }
-      if (foundNonWhitespace) {
-        lexer.undo();
-        break;
-      }
-    }
-  }
