+      Preconditions.checkNotNull(pattern);
+      checkHelper(helper);
+
+      String punycodePattern = toPunycodePattern(pattern);
+      Preconditions.checkArgument(
+          DOMAIN_PATTERN.matcher(punycodePattern).matches(),
+          "Pattern '%s' is not a valid (wildcard) DNS name",
