+    throw new UnsupportedOperationException("Not implemented yet");
+  }
+
+  public void explain(ImmutableSet<ModuleKey> targets) {
+    throw new UnsupportedOperationException("Not implemented yet");
+  }
+
+  public void show(ImmutableSet<ModuleKey> targets) {
+    throw new UnsupportedOperationException("Not implemented yet");
+  }
