+    RuleConfiguredTarget configuredTarget = new RuleConfiguredTarget(
+        target.getLabel(),
+        configuration.getKey(),
+        convertVisibility(target),
+        providerBuilder.build(),
+        configConditions.asProviders(),
+        ruleClassString);
